SELECT
    (SELECT COUNT(*)
     FROM card_payment_approvals approval
     WHERE approval.user_id = #{userId}
       AND approval.user_card_id = #{userCardId}
       AND approval.approved_at >= CONCAT(#{yearMonth}, '-01')
       AND approval.approved_at < DATE_ADD(CONCAT(#{yearMonth}, '-01'), INTERVAL 1 MONTH)
    ) AS approval_count,
    (SELECT COUNT(*)
     FROM user_benefit_calculation_outcomes outcome
     WHERE outcome.user_card_id = #{userCardId}
       AND outcome.usage_date >= CONCAT(#{yearMonth}, '-01')
       AND outcome.usage_date < DATE_ADD(CONCAT(#{yearMonth}, '-01'), INTERVAL 1 MONTH)
    ) AS outcome_count,
    (SELECT COUNT(*)
     FROM user_benefit_usages usage_row
     WHERE usage_row.user_card_id = #{userCardId}
       AND usage_row.usage_status = 'confirmed'
       AND usage_row.usage_date >= CONCAT(#{yearMonth}, '-01')
       AND usage_row.usage_date < DATE_ADD(CONCAT(#{yearMonth}, '-01'), INTERVAL 1 MONTH)
    ) AS usage_count


WHERE uc.user_id = #{userId}
  AND uc.user_card_id = #{userCardId}
  AND uc.is_active = TRUE


WHERE uc.user_id = #{userId}
  AND uc.is_active = TRUE
ORDER BY uc.display_order ASC, uc.user_card_id ASC
